const names={overview:pair('经营总览','Overview'),business:pair('业务全景','Business processes'),goods:pair('物流','Goods flow'),cash:pair('资金流','Cash flow'),information:pair('数据流','Information flow'),insights:pair('经营洞察','Business insights'),store:pair('门店经营','Store execution')};
