const skus=[['HC-524C','500mL × 24',pair('纸箱','Carton'),12,72],['HC-512F','500mL × 12',pair('包膜','Shrink-wrap'),6,24],['HC-12512C','1250mL × 12',pair('纸箱','Carton'),15,16],['HC-1256F','1250mL × 6',pair('包膜','Shrink-wrap'),7.5,8]];
