const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function b(label,attrs='',active=false){return `<button type="button" class="cursor-interaction" ${attrs} aria-pressed="${active}">${esc(t(label))}</button>`}
function kpis(items){return `<div class="bc-kpis">${items.map(x=>`<div class="bc-kpi"><small>${esc(t(x[0]))}</small><div class="bc-value">${esc(x[1])}<span>${esc(t(x[2]))}</span></div><small>${esc(t(x[3]||''))}</small></div>`).join('')}</div>`}
function table(cols,rows){return `<div class="bc-table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(t(c))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(t(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function bars(rows,unit){const max=Math.max(...rows.map(x=>x[2]),1);return `<div class="bc-bars">${rows.map(x=>`<div><div class="bc-row bc-between"><span>${esc(t([x[0],x[1]]))}</span><strong>${x[2]} <small>${esc(t(unit))}</small></strong></div><div class="bc-track"><div class="bc-fill" style="width:${x[2]/max*100}%"></div></div></div>`).join('')}</div>`}
