const fmt=n=>Number(n.toFixed(2)).toLocaleString(state.lang==='zh'?'zh-CN':'en-US',{maximumFractionDigits:2});
function apportion(total,weights){let remaining=Math.round(total*100);return weights.map((w,i)=>{const n=i===weights.length-1?remaining:Math.round(total*w);remaining-=n;return n/100})}
const regions=territories.flatMap(g=>{const w=g.provinces.map(p=>p[2]),ss=apportion(g.sales,w),dd=apportion(g.demand,w),sp=apportion(g.supply,w);return g.provinces.map((p,i)=>{let demand=dd[i],supply=sp[i];if(g.id==='south'){supply=p[0]==='440000'?14:demand;}return [p[0],geo.find(f=>f.id===p[0]).name,p[1],({'440000':12.8,'330000':15.2,'320000':13.6,'420000':10.2,'510000':9.4,'410000':8.6}[p[0]]||+(g.share+(i%3-1)*.7).toFixed(1)),ss[i],demand,supply,({'440000':91.2,'330000':96.1,'420000':97.4}[p[0]]||+(100*g.delivered/g.orders).toFixed(1)),6+i%4,g.id]})});
