function costOptions(){return [{id:'A',label:pair('自有工厂加产4万箱','Own factory +40k'),parts:[12,2,2,1,1],cash:44,transfer:0,quality:true},{id:'B',label:pair('调拨2万＋自制2万','Transfer20k + make20k'),parts:[6,0,12,3,4],cash:32,transfer:2,quality:true},{id:'C',label:pair('跨仓调拨4万箱','Transfer40k'),parts:[0,0,26,2,4],cash:20,transfer:4,quality:true},{id:'D',label:pair('代工4万箱','Co-pack40k'),parts:[10,4,3,2,1],cash:28,transfer:0,quality:state.copackReady}].map(o=>({...o,total:o.parts.reduce((a,b)=>a+b,0),feasible:o.cash<=state.budget&&o.transfer<=(state.hold?0:2)&&o.quality}));}
function coordination(){const n=coreNodes.find(n=>n[0]===state.core)||coreNodes[1],cost=state.caseStudy==='cost',cs=businessCases[state.caseStudy]||businessCases.cold;
main.innerHTML=heading(pair('企业经营协同','Enterprise operating decisions'),pair('经营目标 → 跨域判断 → 责任与反馈','Objectives → cross-domain judgment → accountability'))+`<section class="bc-panel"><h2>${t(pair('经营闭环','Operating loops'))}</h2>${[[pair('产品与计划','Product & planning'),coreNodes.slice(0,4)],[pair('制造与供给','Manufacturing & supply'),coreNodes.slice(4,8)],[pair('客户与增长','Customers & growth'),coreNodes.slice(8)]].map(([label,ns])=>`<div class="bc-lane"><h3>${t(label)}</h3><div class="bc-chain">${ns.map(x=>b([x[2],x[3]],`data-core="${x[0]}"`,n[0]===x[0])).join('')}</div></div>`).join('')}<div class="bc-two bc-section"><div><small>${t(pair('当前经营事实','OPERATING EVIDENCE'))}</small><h2>${t([n[2],n[3]])}</h2><p class="bc-small">${t([n[4],n[5]])}</p><p class="bc-section">${t([n[6],n[7]])}</p></div><div class="bc-note"><strong>${t(pair('跨部门判断与行动','Cross-functional assessment & action'))}</strong><p>${t([n[8],n[9]])}</p><small>${t([n[10],n[11]])}</small><div class="bc-section">${b(pair('展开业务流程','Open business process'),`data-domain="${n[1]}"`)}${['crm','loyalty','lifecycle'].includes(n[0])?b(pair('客户与会员详情','Customer & loyalty details'),'data-page="customers"'):''}</div></div></div></section><section class="bc-panel bc-section"><h2>${t(pair('经营决策事项','Operating decisions'))}</h2><div class="bc-tabs">${Object.entries(businessCases).map(([id,x])=>b(x[0],`data-case-study="${id}"`,state.caseStudy===id)).join('')}${b(pair('供给全流程成本','End-to-end supply cost'),'data-case-study="cost"',cost)}</div>${cost?costPanel():`<h2>${t(cs[1])}</h2><div class="bc-two bc-section">${[pair('已知事实','Evidence'),pair('关联判断 / 待核原因','Assessment / alternatives'),pair('建议与前置条件','Recommendation / prerequisites'),pair('责任与时间','Owners & timing')].map((label,i)=>`<div class="bc-evidence"><small>${t(label)}</small><p>${t(cs[i+2])}</p></div>`).join('')}</div><div class="bc-note"><strong>${t(pair('结果核验','Outcome review'))}</strong><p>${t(cs[6])}</p></div>`}</section>`;
}
function costPanel(){const options=costOptions(),best=options.filter(o=>o.feasible).sort((a,b)=>a.total-b.total)[0];return `<h2>${t(pair('广东HC-524C · 4万箱保供决策','Guangdong HC-524C ·40k-case supply decision'))}</h2><div class="bc-two bc-section"><div><small>${t(pair('增量现金上限 / 万元','Incremental cash cap / CNY10k'))}</small><div class="bc-tabs">${[25,35,50].map(v=>b(String(v),`data-cost-budget="${v}"`,state.budget===v)).join('')}</div><small>${t(pair('武汉调出状态','Wuhan transfer status'))}</small><div class="bc-tabs">${b(pair('可调2万箱','20k transferable'),'data-cost-hold="false"',!state.hold)}${b(pair('暂停调出','Transfers held'),'data-cost-hold="true"',state.hold)}</div></div><div><small>${t(pair('代工质量与履约前置','Co-pack quality & delivery prerequisites'))}</small><div class="bc-tabs">${b(pair('待核实','Pending verification'),'data-copack="false"',!state.copackReady)}${b(pair('条件已满足','Conditions satisfied'),'data-copack="true"',state.copackReady)}</div><p class="bc-small">${t(pair('资格、包材齐套、产能、10.15交期与批次放行共同核实。','Verify qualification, materials, capacity, Oct15 delivery and lot release.'))}</p></div></div>${table(t(pair(['方案','制造/加工','换型/准备','运输','检验/处理','持有/损耗','总成本','现金','结果'],['Plan','Make','Setup','Freight','QA/handling','Hold/loss','Total','Cash','Status'])),options.map(o=>[o.id+' · '+t(o.label),...o.parts,o.total,o.cash,o.feasible?pair('可行候选','Feasible candidate'):!o.quality?pair('前置未满足','Prerequisites unmet'):o.cash>state.budget?pair('超过现金上限','Cash cap exceeded'):pair('超过可调量','Transfer limit exceeded')]))}<div id="bc-cost-result" class="bc-note"><strong>${best?t(pair('当前候选最低成本：','Lowest-cost feasible candidate: '))+best.id:t(pair('无完整可行方案','No complete feasible option'))}</strong><p>${t(pair('满足质量、交期和服务前置后比较增量成本；方案待批准，原经营任务尚未下达。金额单位：万元。','Compare incremental cost after quality, delivery and service prerequisites; approval pending, operating orders not released. Amounts: CNY10k.'))}</p></div>`}
