function allocateWhole(total,weights){const sum=weights.reduce((a,b)=>a+b,0),raw=weights.map(w=>total*w/sum),values=raw.map(Math.floor),missing=total-values.reduce((a,b)=>a+b,0),rank=raw.map((x,i)=>({i,r:x-values[i]})).sort((a,b)=>b.r-a.r||a.i-b.i);for(let i=0;i<missing;i++)values[rank[i%rank.length].i]++;return values;}
function monthWeights(cat,region,year){return cat.season.map((_,i)=>{let v=cat.season[region.id==='AUS'?(i+6)%12:i];if(['VNM','THA','MYS','IDN'].includes(region.id))v=1+(v-1)*.35;if(region.id==='north')v=1+(v-1)*1.2;if(region.id==='south')v=1+(v-1)*.8;if(region.domestic&&['juice','soft','beer'].includes(cat.id)){if(i===(year===2025?0:1))v*=1.13;if(i===(year===2025?1:0))v*=.95;}return v;});}
const operatingCube=ports.data.operatingCube;
