function periodMonths(period=state.reportPeriod,year=state.fiscalYear){if(period==='ytd')return Array.from({length:year===2026?9:12},(_,i)=>i+1);if(period==='year')return Array.from({length:12},(_,i)=>i+1);if(period.startsWith('q')){const start=(Number(period[1])-1)*3;return [start+1,start+2,start+3];}return [Number(period.slice(1))];}
function periodName(period=state.reportPeriod,year=state.fiscalYear){if(period==='ytd')return year===2026?pair('1–9月累计','Jan–Sep YTD'):pair('全年累计','Full-year YTD');if(period==='year')return pair('全年','Full year');if(period.startsWith('q'))return pair('第'+period[1]+'季度','Q'+period[1]);return pair(Number(period.slice(1))+'月',new Date(2025,Number(period.slice(1))-1).toLocaleString('en-US',{month:'short'}));}
function periodStatus(){return state.fiscalYear===2025||Math.max(...periodMonths())<=9?pair('已结账','Closed actuals'):Math.min(...periodMonths())>=10?pair('滚动预测','Rolling forecast'):pair('1–9月实绩 + 10–12月预测','Jan–Sep actuals + Oct–Dec forecast');}
function portfolioRows(filter={},year=state.fiscalYear,months=periodMonths()){return operatingCube.filter(r=>r.year===year&&months.includes(r.month)&&Object.entries(filter).every(([k,v])=>r[k]===v));}
function aggregate(rows){const out={revenue:0,cases:0,liters:0,grossProfit:0,opProfit:0,target:0,demand:0,supply:0,due:0,delivered:0,ka:0};for(const r of rows){for(const k of ['revenue','cases','liters','grossProfit','opProfit','target','demand','supply','due','ka'])out[k]+=r[k];out.delivered+=Math.round(r.due*r.otif);}out.otif=out.due?100*out.delivered/out.due:0;return out;}
const moneyUnit=()=>pair('亿元','CNY100m');
const money=x=>fmt(x/10000);
