 '810000':[['九龙城区','Kowloon City'],['沙田区','Sha Tin']], '820000':[['澳门半岛','Macao Peninsula'],['氹仔','Taipa']],
 '500000':[['渝北区','Yubei'],['江北区','Jiangbei']], '510000':[['成都','Chengdu'],['绵阳','Mianyang'],['宜宾','Yibin']],
