const v9Risks=[{id:'supply',name:v9L('渠道促销早于供货','Promotion precedes supply','販促開始前の供給不足'),impact:v9L('8万箱未覆盖','80k cases uncovered','8万ケースの不足'),cause:v9L('四SKU共识需求120万箱，可供112万箱；隔离3万箱不计可供。','Four-SKU consensus120, supply112; held3 excluded (10k cases).','4SKUの需要120万ケースに対し供給112万。隔離3万は供給に含めない。'),action:v9L('先保已承诺客户，再比较代工与调拨；不把促销增量重复计入订单。','Protect committed customers; compare co-pack and transfers without double-counting promotion.','確約済み顧客を優先し、委託生産と拠点間移送を比較。販促増分を二重計上しない。'),domain:'plan',step:1,owner:'Planning lead'}, {id:'cash',name:v9L('收入已确认，现金未到位','Revenue recognized; cash outstanding','売上計上済み・入金未了'),impact:v9L('逾期180万元','CNY1.8m overdue','延滞180万元'),cause:v9L('期末应收1600万元，其中C-102逾期180万元；对应发票与收款可核对。','Closing AR1600 CNY10k; C-102 overdue180, linked to invoice and receipts.','売掛金1,600万元のうちC-102の180万元が延滞。請求と入金を照合可能。'),action:v9L('客户经理与财务核回款承诺；新增授信单独审批。','Account lead and Finance verify collection promises; new credit requires separate approval.','営業と財務で入金予定を確認。追加与信は別途承認。'),domain:'finance',step:1,owner:'Finance lead'}, {id:'pack',name:v9L('新品切换与旧包材冲突','New launch conflicts with old packaging','新商品切替と旧包材の競合'),impact:v9L('旧料及未交38万件','380k old-pack units exposed','旧包材38万個が対象'),cause:v9L('旧料18万件、未交20万件；新增24万件MOQ尚未批准。','180k old stock +200k open PO; further240k MOQ unapproved.','旧在庫18万個＋未納20万個。追加MOQ24万個は未承認。'),action:v9L('先确认BOM生效日与预计消耗，再决定切换和采购。','Confirm BOM effectivity and consumption before pack transition and purchasing.','BOM適用日と消費見込みを確認してから切替・発注を判断。'),domain:'product',step:3,owner:'Product director'}];
function v9RiskPanel(){return `<section class="v9-risks"><h2>${t(v9L('经营关联与待决事项','Connected risks & decisions','業務横断リスクと判断事項'))}</h2><div class="v9-risk-grid">${v9Risks.map(r=>`<article><small>${t(r.owner)}</small><h3>${t(r.name)}</h3><strong>${t(r.impact)}</strong><p>${t(r.cause)}</p><details><summary>${t(v9L('处置与约束','Response & constraints','対応と制約'))}</summary><p>${t(r.action)}</p></details>${b(v9L('查看单据与流程 →','Documents & process →','伝票・プロセスへ →'),`data-v9-open="${r.domain}" data-v9-step="${r.step}"`)}</article>`).join('')}</div></section>`;}
const v8BusinessBeforeV9=business;business=function(){v8BusinessBeforeV9();main.insertAdjacentHTML('beforeend',v9RiskPanel()+v9LedgerPanel());};
const v8GoodsBeforeV9=goods;goods=function(){v8GoodsBeforeV9();main.insertAdjacentHTML('beforeend',`<section class="v9-ledger"><h2>${t(v9L('SKU库存收发存','Inventory roll-forward by SKU','SKU別在庫受払'))}</h2>${table(t(v9L(['SKU','期初','入库','出库','期末','可用','待检','隔离'],['SKU','Opening','Received','Shipped','Closing','Released','Inspection','Held'],['SKU','期首','入庫','出庫','期末','使用可','検査待','隔離'])),v9Skus.map(s=>[s[0],s[5],s[6],s[4],s[7],s[8],s[9],s[10]]))}<small>${t(v9L('单位：万箱 · 10.01–10.11 · 承诺与安全余量在可用量内继续扣减','10k cases · Oct1–11 · commitments and reserve further reduce availability','単位：万ケース・10月1～11日・引当と安全在庫をさらに控除'))}</small></section>`);};
const v8CoordBeforeV9=coordination;coordination=function(){v8CoordBeforeV9();if(state.networkTab!=='detail'){const p=networkOptions().find(p=>p.id===state.networkPlan);main.insertAdjacentHTML('beforeend',`<section class="v9-ledger"><h2>${t(v9L('批准、执行与财务凭据','Approval, execution & financial evidence','承認・実行・財務証憑'))}</h2>${table(t(v9L(['事项','业务凭据','状态','数量/金额'],['Item','Evidence','Status','Quantity / amount'],['事項','証憑','状態','数量・金額'])),[[v9L('共同决策','Joint decision','共同判断'),'OP-20261012-01',state.networkStage==='draft'?v9L('待审批','Awaiting approval','承認待ち'):v9L('已批准','Approved','承認済み'),p.coverage+' ×10k cases'],...[[0,'MES-QA-1015',p.own],[1,'POD-1014',p.transfer],[2,'CM-QA-1015',p.copack]].map(([i,ref,q])=>[i===0?v9L('自产','Own production','自社生産'):i===1?v9L('调拨','Transfer','拠点間移送'):v9L('代工','Co-pack','委託生産'),ref,state.networkReceipts.includes(i)?v9L('已签收核验','Receipt verified','受領確認済み'):v9L('待执行凭据','Evidence pending','証憑待ち'),q+' ×10k cases']),[v9L('付款核验','Payment verification','支払照合'),'PAY-20261015',state.networkPaid?v9L('已核验','Verified','照合済み'):v9L('未付款','Not paid','未払い'),(state.networkPaid?p.cash:0)+' CNY10k']] )}</section>`);}};
root.addEventListener('click',e=>{const el=e.target.closest('[data-v9-document],[data-v9-close],[data-v9-open]');if(!el)return;const d=el.dataset;if(d.v9Document){state.documentId=d.v9Document;state.documentDomain=d.v9Domain;state.documentStage=Number(d.v9Stage);}if(d.v9Close!==undefined)state.documentId=null;if(d.v9Open){state.page='business';state.domain=d.v9Open;state.step=Number(d.v9Step);state.documentId=null;}render();save();if(d.v9Document)main.querySelector('.v9-document')?.scrollIntoView({block:'nearest'});});

