// Ordered, adjacent handoffs only. / 只连接顺序相邻的业务交接。
function v11FlowPositions(count, width, maxColumns = 5) {
  const columns = Math.min(count, maxColumns, width >= 920 ? 5 : width >= 620 ? 3 : 1);
  return Array.from({length: count}, (_, index) => {
    const row = Math.floor(index / columns);
    const offset = index % columns;
    return {index, row, column: row % 2 === 0 ? offset : columns - 1 - offset, columns};
  });
}
function v11HandoffRoute(a, b) {
  const middleY = q => q.y + q.height / 2;
  const middleX = q => q.x + q.width / 2;
  let points;
  if (Math.abs(middleY(a) - middleY(b)) < 2) {
    const forward = b.x > a.x;
    points = forward
      ? [[a.x + a.width + 1, middleY(a)], [b.x - 5, middleY(b)]]
      : [[a.x - 1, middleY(a)], [b.x + b.width + 5, middleY(b)]];
  } else if (Math.abs(middleX(a) - middleX(b)) < 2 && b.y > a.y) {
    points = [[middleX(a), a.y + a.height + 1], [middleX(b), b.y - 5]];
  } else {
    // Fail closed instead of drawing through another node. / 布局不满足相邻端口时不画线。
    return null;
  }
  const n = value => Math.round(value * 2) / 2;
  return {points: points.map(p => p.map(n)), d: points.map((p, i) => `${i ? 'L' : 'M'}${n(p[0])},${n(p[1])}`).join(' ')};
}

