function v11DrawMaps() {
  main.querySelectorAll('.v11-track').forEach(track => {
    const cards = [...track.querySelectorAll('.v11-process')];
    const width = track.getBoundingClientRect().width;
    if (width <= 0) return;
    const positions = v11FlowPositions(cards.length, width, Number(track.dataset.maxColumns));
    const columns = positions[0]?.columns || 1;
    track.style.setProperty('--v11-columns', columns);
    cards.forEach((card, index) => {
      const p = positions[index];
      card.style.gridColumn = String(p.column + 1);
      card.style.gridRow = String(p.row + 1);
    });
    const bounds = track.getBoundingClientRect();
    const rectangles = cards.map(card => {
      const r = card.getBoundingClientRect();
      return {x: r.left - bounds.left, y: r.top - bounds.top, width: r.width, height: r.height};
    });
    const svg = track.querySelector('.v11-edges');
    const marker = 'v11-arrow-' + track.dataset.track;
    svg.setAttribute('viewBox', `0 0 ${bounds.width} ${bounds.height}`);
    svg.innerHTML = `<defs><marker id="${marker}" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="currentColor"/></marker></defs>` + rectangles.slice(0, -1).map((rect, index) => {
      const route = v11HandoffRoute(rect, rectangles[index + 1]);
      if (!route) return '';
      return `<path class="v11-edge" data-from="${index}" data-to="${index + 1}" data-kind="${cards[index].querySelector('.v11-output').dataset.kind}" d="${route.d}" marker-end="url(#${marker})"/>`;
    }).join('');
    track.dataset.columns = String(columns);
    track.dataset.routeCount = String(svg.querySelectorAll('.v11-edge').length);
  });
}
